head.script:
scwin.__getObj = function(id) {
	if (typeof id !== 'string') return id;
	var W = WebSquare, C = W.idCache, U = W.idToUUID, F = function(k) { return new Function('return ' + k)(); };
	if (!W.strictMode) id = id.replace(/mf_/g, '');
	if (C[U[id]]) return C[U[id]];
	var r; try { r = F(id); } catch (e) {}
	if (r == undefined && W.strictMode) {
		var P = W.strictModeFrame.id + '_';
		var s = id.slice(0, 2) === 'G_' ? 'G_' + P + id.slice(2) : (id.slice(0, P.length) !== P ? P + id : id);
		s = s.replace(new RegExp('(' + P + '){2,}', 'g'), P);
		if (C[U[s]]) r = C[U[s]]; else { try { r = F(s); } catch (e) { r = id; } }
	}
	return r == undefined ? id : r;
};
scwin.trigger1_onclick = function(e) {
	var focus_label = treeview1.getSelectedLabel();
	var sel_idx = treeview1.getSelectedIndex();
	var aa = dl_tree1.getMatchedData("menu_nm", focus_label);
	if (aa.length > 0) {
		return false;
	} else {
		var idx = dl_tree1.getRowCount();
		var vobj = dl_tree.getRowJSON(sel_idx - 1);
		vobj.menu_no = 3;
		dl_tree1.setRowJSON(idx, vobj);
	}
};
scwin.trigger2_onclick = function(e) {
	var focus_label = treeview2.getSelectedLabel();
	var sel_idx = treeview2.getSelectedIndex();
	if (sel_idx == "") {
		return false;
	} else {
		dl_tree1.removeRow(sel_idx - 1);
	}
};
scwin.__isCheckLog = function() {
	return WebSquare.logger.getErrorLog() == "";
};
scwin.checkVal = function() {
	return typeof scwin.__getObj('treeview2_label_3') == "object";
};
scwin.onpageload = function() {
	var jsonData1 = [
		{"menu_no": 1, "menu_nm": "공통", "level": "1"},
		{"menu_no": 2, "menu_nm": "공통1", "level": "2"},
		{"menu_no": 3, "menu_nm": "공통1-1", "level": "3"},
		{"menu_no": 4, "menu_nm": "수신", "level": "1"},
		{"menu_no": 5, "menu_nm": "수신1", "level": "2"},
		{"menu_no": 6, "menu_nm": "여신", "level": "1"},
		{"menu_no": 7, "menu_nm": "고객", "level": "1"}
	];
	var jsonData2 = [
		{"menu_no": 1, "menu_nm": "공통", "level": "1"},
		{"menu_no": 2, "menu_nm": "고객", "level": "1"}
	];
	dl_tree.setJSON(jsonData1);
	dl_tree1.setJSON(jsonData2);
};
